E = {'🍽️':'utensils','🛏️':'bed','🛏':'bed','🚿':'shower','🍳':'pot','🍲':'pot','🧊':'fridge','🔥':'flame','📺':'tv','📷':'camera','🧘':'user','🚐':'bus','🏊':'waves','🅿️':'parking','📶':'wifi','🏛️':'temple','🚉':'train','🌅':'ruler','☕':'coffee','🐾':'paw','♿':'wheelchair','🛗':'lift','🔋':'battery','❄️':'snow','🕥':'clock','🕐':'clock','👥':'users','💬':'chat','📧':'mail','📍':'pin','✈️':'plane','🚙':'car','🚗':'car','🪔':'flame','📞':'phone','💯':'badge'}
def svg(name):
    return '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' + ''.join(f'<path d="{d}"/>' for d in P[name]) + '</svg>'
keys = sorted(E, key=len, reverse=True)
alt = '|'.join(re.escape(k) for k in keys)
n = 0
for f in glob.glob('*.html') + glob.glob('blog/*.html'):
    s = open(f).read(); o = s
    # icon slots: <span class="amenity__icon">🍽️</span>, contact-card__icon, travel icons
    s = re.sub(r'(class="(?:amenity__icon|contact-card__icon|travel-cat-icon|travel-feature__icon)"[^>]*>)\s*(' + alt + r')\s*(<)', lambda m: m.group(1) + svg(E[m.group(2)]) + m.group(3), s)
    # villa card meta: <span>🛏 3 Bedrooms</span>
    s = re.sub(r'(<div class="villa-card__meta">[\s\S]*?</div>)', lambda m: re.sub(r'<span>(' + alt + r')\s*', lambda k: '<span>' + svg(E[k.group(1)]), m.group(1)), s)
    if s != o: open(f, 'w').write(s); n += 1
print('pages updated', n)
